import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"模板类型","description":"","frontmatter":{},"headers":[],"relativePath":"reference/schema.md","filePath":"reference/schema.md","lastUpdated":1792400349000}`),a={name:`reference/schema.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="模板类型" tabindex="-1">模板类型 <a class="header-anchor" href="#模板类型" aria-label="Permalink to “模板类型”">​</a></h1><p>表单文档 <code>FormDocument</code> 的全部类型，按 <code>@xihan-form/core</code> 的源码列出。当前结构版本 <code>FORM_SCHEMA_VERSION</code> 为 <code>1</code>。</p><p>各种类的属性包里有哪些属性见<a href="./kinds">种类与属性</a>。</p><h2 id="文档、节点与规则" tabindex="-1">文档、节点与规则 <a class="header-anchor" href="#文档、节点与规则" aria-label="Permalink to “文档、节点与规则”">​</a></h2><h3 id="propertybag" tabindex="-1">PropertyBag <a class="header-anchor" href="#propertybag" aria-label="Permalink to “PropertyBag”">​</a></h3><p>属性包：一组按名字存放的 JSON 值。</p><p>类型：<code>Readonly&lt;Record&lt;string, JsonValue&gt;&gt;</code></p><h3 id="extensiondata" tabindex="-1">ExtensionData <a class="header-anchor" href="#extensiondata" aria-label="Permalink to “ExtensionData”">​</a></h3><p>扩展数据：扩展 id → 这个扩展自己的 JSON 对象。只给扩展用，与业务属性分开；编辑与复制粘贴原样带着走。</p><p>类型：<code>Readonly&lt;Record&lt;string, JsonObject&gt;&gt;</code></p><h3 id="propertygroup" tabindex="-1">PropertyGroup <a class="header-anchor" href="#propertygroup" aria-label="Permalink to “PropertyGroup”">​</a></h3><p>节点的属性分组：基础、数据、外观。校验与联动另以规则列表存放。</p><p>类型：<code>&#39;basic&#39; | &#39;data&#39; | &#39;appearance&#39;</code></p><h3 id="requiredrule" tabindex="-1">RequiredRule <a class="header-anchor" href="#requiredrule" aria-label="Permalink to “RequiredRule”">​</a></h3><p>必填：值为空时不通过，空值判定取 <code>@xihan-ui/headless</code> 的 <code>isEmptyFormValue</code>：null、只含空白的字符串、空列表与元素全为空的列表算空，<code>false</code> 与 <code>0</code> 不算空。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>规则 id，在所在规则列表里唯一；设计器编辑与问题定位都按它找规则。</td></tr><tr><td><code>kind</code></td><td><code>&#39;required&#39;</code></td><td>是</td><td>规则种类。</td></tr><tr><td><code>message</code></td><td><code>string</code></td><td>可省</td><td>不通过时给最终用户看的提示；不写时由运行时按问题码给出缺省文案。</td></tr></tbody></table><h3 id="acceptedrule" tabindex="-1">AcceptedRule <a class="header-anchor" href="#acceptedrule" aria-label="Permalink to “AcceptedRule”">​</a></h3><p>必须为 <code>true</code>：用于「必须勾选同意」，值为 <code>false</code> 或空时都不通过。只适用于布尔值字段。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>规则 id，在所在规则列表里唯一；设计器编辑与问题定位都按它找规则。</td></tr><tr><td><code>kind</code></td><td><code>&#39;accepted&#39;</code></td><td>是</td><td>规则种类。</td></tr><tr><td><code>message</code></td><td><code>string</code></td><td>可省</td><td>不通过时给最终用户看的提示；不写时由运行时按问题码给出缺省文案。</td></tr></tbody></table><h3 id="lengthrule" tabindex="-1">LengthRule <a class="header-anchor" href="#lengthrule" aria-label="Permalink to “LengthRule”">​</a></h3><p>长度：字符串按字素计（<code>@xihan-ui/headless</code> 的 <code>graphemeLength</code>，与文本框的字数一致）、列表按元素个数，闭区间。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>规则 id，在所在规则列表里唯一；设计器编辑与问题定位都按它找规则。</td></tr><tr><td><code>kind</code></td><td><code>&#39;length&#39;</code></td><td>是</td><td>规则种类。</td></tr><tr><td><code>min</code></td><td><code>number</code></td><td>可省</td><td>最少多少个字符或元素。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td>可省</td><td>最多多少个字符或元素。</td></tr><tr><td><code>message</code></td><td><code>string</code></td><td>可省</td><td>不通过时给最终用户看的提示；不写时由运行时按问题码给出缺省文案。</td></tr></tbody></table><h3 id="rangerule" tabindex="-1">RangeRule <a class="header-anchor" href="#rangerule" aria-label="Permalink to “RangeRule”">​</a></h3><p>数值范围，闭区间。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>规则 id，在所在规则列表里唯一；设计器编辑与问题定位都按它找规则。</td></tr><tr><td><code>kind</code></td><td><code>&#39;range&#39;</code></td><td>是</td><td>规则种类。</td></tr><tr><td><code>min</code></td><td><code>number</code></td><td>可省</td><td>下限。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td>可省</td><td>上限。</td></tr><tr><td><code>message</code></td><td><code>string</code></td><td>可省</td><td>不通过时给最终用户看的提示；不写时由运行时按问题码给出缺省文案。</td></tr></tbody></table><h3 id="patternrule" tabindex="-1">PatternRule <a class="header-anchor" href="#patternrule" aria-label="Permalink to “PatternRule”">​</a></h3><p>正则：<code>flags</code> 只允许 <code>i</code>、<code>m</code>、<code>s</code>、<code>u</code>，整串不匹配即不通过。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>规则 id，在所在规则列表里唯一；设计器编辑与问题定位都按它找规则。</td></tr><tr><td><code>kind</code></td><td><code>&#39;pattern&#39;</code></td><td>是</td><td>规则种类。</td></tr><tr><td><code>pattern</code></td><td><code>string</code></td><td>是</td><td>正则的源码，不带两边的斜杠。</td></tr><tr><td><code>flags</code></td><td><code>string</code></td><td>可省</td><td>正则标志。</td></tr><tr><td><code>message</code></td><td><code>string</code></td><td>可省</td><td>不通过时给最终用户看的提示；不写时由运行时按问题码给出缺省文案。</td></tr></tbody></table><h3 id="expressionrule" tabindex="-1">ExpressionRule <a class="header-anchor" href="#expressionrule" aria-label="Permalink to “ExpressionRule”">​</a></h3><p>表达式：结果为 <code>false</code> 时不通过，为 <code>true</code> 或 <code>null</code> 时通过。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>规则 id，在所在规则列表里唯一；设计器编辑与问题定位都按它找规则。</td></tr><tr><td><code>kind</code></td><td><code>&#39;expression&#39;</code></td><td>是</td><td>规则种类。</td></tr><tr><td><code>expression</code></td><td><code>string</code></td><td>是</td><td>受限表达式，<code>$value</code> 是字段自己的值。</td></tr><tr><td><code>message</code></td><td><code>string</code></td><td>可省</td><td>不通过时给最终用户看的提示；不写时由运行时按问题码给出缺省文案。</td></tr></tbody></table><h3 id="validationrule" tabindex="-1">ValidationRule <a class="header-anchor" href="#validationrule" aria-label="Permalink to “ValidationRule”">​</a></h3><p>声明式校验规则。<code>message</code> 是模板作者写给最终用户的提示，缺省时由运行时按规则种类给出。</p><p>取其一：<code><a href="#requiredrule">RequiredRule</a></code>、<code><a href="#acceptedrule">AcceptedRule</a></code>、<code><a href="#lengthrule">LengthRule</a></code>、<code><a href="#rangerule">RangeRule</a></code>、<code><a href="#patternrule">PatternRule</a></code>、<code><a href="#expressionrule">ExpressionRule</a></code>。</p><h3 id="validationkind" tabindex="-1">ValidationKind <a class="header-anchor" href="#validationkind" aria-label="Permalink to “ValidationKind”">​</a></h3><p>校验规则的种类。</p><p>类型：<code><a href="#validationrule">ValidationRule</a>[&#39;kind&#39;]</code></p><h3 id="linkageaction" tabindex="-1">LinkageAction <a class="header-anchor" href="#linkageaction" aria-label="Permalink to “LinkageAction”">​</a></h3><p>联动动作：条件成立时生效，不成立时回到节点的静态设定。</p><ul><li><code>show</code> / <code>hide</code>：显示 / 隐藏。</li><li><code>enable</code> / <code>disable</code>：可用 / 禁用。</li><li><code>require</code> / <code>optional</code>：设为必填 / 取消必填。</li><li><code>assign</code>：把 <code>value</code> 表达式的结果赋给字段。</li></ul><p>类型：<code>&#39;show&#39; | &#39;hide&#39; | &#39;enable&#39; | &#39;disable&#39; | &#39;require&#39; | &#39;optional&#39; | &#39;assign&#39;</code></p><h3 id="linkagerule" tabindex="-1">LinkageRule <a class="header-anchor" href="#linkagerule" aria-label="Permalink to “LinkageRule”">​</a></h3><p>声明式联动规则；<code>when</code> 缺省表示总是成立。同一状态有多条规则成立时，排在后面的生效。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>规则 id，在所在规则列表里唯一。</td></tr><tr><td><code>action</code></td><td><code><a href="#linkageaction">LinkageAction</a></code></td><td>是</td><td>条件成立时做什么。</td></tr><tr><td><code>when</code></td><td><code>string</code></td><td>可省</td><td>条件，受限表达式，结果为 <code>true</code> 时成立；缺省总是成立。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td>可省</td><td><code>assign</code> 的取值，受限表达式；其它动作不用。</td></tr></tbody></table><h3 id="fieldnode" tabindex="-1">FieldNode <a class="header-anchor" href="#fieldnode" aria-label="Permalink to “FieldNode”">​</a></h3><p>字段：有数据键与值。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>&#39;field&#39;</code></td><td>是</td><td>节点类型。</td></tr><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>节点 id，在整份文档里唯一。</td></tr><tr><td><code>kind</code></td><td><code>string</code></td><td>是</td><td>种类，如 <code>text</code>、<code>select</code>，决定渲染方式与可用的属性。</td></tr><tr><td><code>key</code></td><td><code>string</code></td><td>是</td><td>数据键：字段的值在表单数据里的键，在所在作用域里唯一。</td></tr><tr><td><code>basic</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>基础属性，如标签、提示、初始值、隐藏与禁用。</td></tr><tr><td><code>data</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>数据属性，如选项、精度、数据来源。</td></tr><tr><td><code>appearance</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>外观属性，如尺寸、前后缀。</td></tr><tr><td><code>validation</code></td><td><code>readonly <a href="#validationrule">ValidationRule</a>[]</code></td><td>是</td><td>校验规则。</td></tr><tr><td><code>linkage</code></td><td><code>readonly <a href="#linkagerule">LinkageRule</a>[]</code></td><td>是</td><td>联动规则。</td></tr><tr><td><code>extensions</code></td><td><code><a href="#extensiondata">ExtensionData</a></code></td><td>可省</td><td>各扩展放在这个节点上的数据。</td></tr></tbody></table><h3 id="region" tabindex="-1">Region <a class="header-anchor" href="#region" aria-label="Permalink to “Region”">​</a></h3><p>区域：容器里放子节点的一格，如栅格的一列、标签页的一页、表格布局的一个单元格。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>区域 id，在整份文档里唯一。</td></tr><tr><td><code>props</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>区域属性，如栅格的列宽、标签页的标题、表格布局单元格的位置。</td></tr><tr><td><code>children</code></td><td><code>readonly <a href="#formnode">FormNode</a>[]</code></td><td>是</td><td>放在这一格里的节点。</td></tr></tbody></table><h3 id="containernode" tabindex="-1">ContainerNode <a class="header-anchor" href="#containernode" aria-label="Permalink to “ContainerNode”">​</a></h3><p>容器：子节点放在区域里。列表作用域的容器（子表单、子表）带 <code>key</code>，它的值是行对象的列表，区域里字段的键相对于行对象。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>&#39;container&#39;</code></td><td>是</td><td>节点类型。</td></tr><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>节点 id，在整份文档里唯一。</td></tr><tr><td><code>kind</code></td><td><code>string</code></td><td>是</td><td>种类，如 <code>grid</code>、<code>subform</code>，决定渲染方式与可用的属性。</td></tr><tr><td><code>key</code></td><td><code>string</code></td><td>可省</td><td>数据键：只有列表容器有，值是行对象的列表。</td></tr><tr><td><code>basic</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>基础属性，如标签、提示、初始值、隐藏与禁用。</td></tr><tr><td><code>data</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>数据属性，如选项、精度、数据来源。</td></tr><tr><td><code>appearance</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>外观属性，如尺寸、前后缀。</td></tr><tr><td><code>validation</code></td><td><code>readonly <a href="#validationrule">ValidationRule</a>[]</code></td><td>是</td><td>校验规则：只对列表容器的整份列表生效。</td></tr><tr><td><code>linkage</code></td><td><code>readonly <a href="#linkagerule">LinkageRule</a>[]</code></td><td>是</td><td>联动规则。</td></tr><tr><td><code>regions</code></td><td><code>readonly <a href="#region">Region</a>[]</code></td><td>是</td><td>区域，按顺序排列。</td></tr><tr><td><code>extensions</code></td><td><code><a href="#extensiondata">ExtensionData</a></code></td><td>可省</td><td>各扩展放在这个节点上的数据。</td></tr></tbody></table><h3 id="staticnode" tabindex="-1">StaticNode <a class="header-anchor" href="#staticnode" aria-label="Permalink to “StaticNode”">​</a></h3><p>静态元素：只展示，没有值，如分隔线、说明文字。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>&#39;static&#39;</code></td><td>是</td><td>节点类型。</td></tr><tr><td><code>id</code></td><td><code>string</code></td><td>是</td><td>节点 id，在整份文档里唯一。</td></tr><tr><td><code>kind</code></td><td><code>string</code></td><td>是</td><td>种类，如 <code>divider</code>、<code>paragraph</code>，决定渲染方式与可用的属性。</td></tr><tr><td><code>basic</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>基础属性，如正文、标题文字与隐藏。</td></tr><tr><td><code>data</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>数据属性。</td></tr><tr><td><code>appearance</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>外观属性，如级别、宽度。</td></tr><tr><td><code>linkage</code></td><td><code>readonly <a href="#linkagerule">LinkageRule</a>[]</code></td><td>是</td><td>联动规则：只有显示与隐藏。</td></tr><tr><td><code>extensions</code></td><td><code><a href="#extensiondata">ExtensionData</a></code></td><td>可省</td><td>各扩展放在这个节点上的数据。</td></tr></tbody></table><h3 id="formnode" tabindex="-1">FormNode <a class="header-anchor" href="#formnode" aria-label="Permalink to “FormNode”">​</a></h3><p>表单节点。</p><p>取其一：<code><a href="#fieldnode">FieldNode</a></code>、<code><a href="#containernode">ContainerNode</a></code>、<code><a href="#staticnode">StaticNode</a></code>。</p><h3 id="nodetype" tabindex="-1">NodeType <a class="header-anchor" href="#nodetype" aria-label="Permalink to “NodeType”">​</a></h3><p>节点类型。</p><p>类型：<code><a href="#formnode">FormNode</a>[&#39;type&#39;]</code></p><h3 id="formdocument" tabindex="-1">FormDocument <a class="header-anchor" href="#formdocument" aria-label="Permalink to “FormDocument”">​</a></h3><p>表单文档：纯 JSON，不含任何代码。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td><code>typeof FORM_SCHEMA_VERSION</code></td><td>是</td><td>结构版本，当前是 <code>FORM_SCHEMA_VERSION</code>。</td></tr><tr><td><code>settings</code></td><td><code><a href="#propertybag">PropertyBag</a></code></td><td>是</td><td>表单设置，如标签位置、尺寸、整表禁用与只读。</td></tr><tr><td><code>children</code></td><td><code>readonly <a href="#formnode">FormNode</a>[]</code></td><td>是</td><td>顶层节点，按顺序排列。</td></tr><tr><td><code>extensions</code></td><td><code><a href="#extensiondata">ExtensionData</a></code></td><td>可省</td><td>各扩展放在文档上的数据。</td></tr></tbody></table><h2 id="options" tabindex="-1">选项 <a class="header-anchor" href="#options" aria-label="Permalink to “选项”">​</a></h2><p>选项：选项列表用 designer-kit 的内建编辑方式 <code>options</code>，选项树用 <code>treeOptions</code>，都要求 label。每项是 <code>{ value: string, label: string, disabled?: boolean, tone?: Tone, description?: string }</code>，选项树的项另可带 <code>children</code>（下一层的选项）与 <code>hasChildren</code>（有子项但还没给出，首次展开时向宿主要）。按 <code>@xihan-ui/core/options</code> 的 <code>findOptionViolation</code> 严格检查：不许多余的键，<code>value</code> 不为空、同一层里不重复，选项树最多 32 层；问题落在那一项的那个键上，如 <code>[2, &quot;value&quot;]</code>、<code>[0, &quot;children&quot;, 1, &quot;label&quot;]</code>。</p>`,67)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};